package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.net.Uri;import android.os.SystemClock;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;

/** A staged Bible becomes available only after a complete, atomic import. */
final class BibleWork {
    static void enqueue(Activity a,Uri uri,String title,int flags){ImportWork.permission(a,uri,flags);PlusUi.run(a,()->{String[] meta=IncomingActivity.metadata(a,uri);String id;try(TaskStore db=new TaskStore(a)){id=db.create("bible","Importar Bíblia · "+title,new JSONObject().put("uri",uri.toString()).put("title",title).put("name",meta[0]).put("mime",meta[1]));}TaskService.launch(a,id);});}
    static void library(Activity a){PagedPicker.show(a,"Escolher Bíblia da biblioteca",(q,offset,limit)->{try(StudyStore db=new StudyStore(a)){BookQuery query=new BookQuery(q,7,0,0,false,Collections.emptySet());List<PagedPicker.Entry> out=new ArrayList<>();try(Cursor r=db.getReadableDatabase().query("materials",null,query.where,query.args,null,null,query.order,offset+","+limit)){while(r.moveToNext()){StudyStore.Row b=TaskStore.row(r);out.add(new PagedPicker.Entry(""+b.id(),b.s("title"),b.s("name")));}}return new PagedPicker.Page(out,db.count("materials",query.where,query.args));}},e->{try(StudyStore db=new StudyStore(a)){StudyStore.Row b=db.get("materials",Long.parseLong(e.id));if(b!=null)enqueue(a,StudyFileProvider.uri(a,b.id()),b.s("title"),0);}});}
    static void run(Context c,StudyStore.Row job,TaskStore work,TaskService.Control control)throws Exception{String id=job.s("id");JSONObject data=new JSONObject(job.s("payload"));File file=new File(SummaryWork.root(c,id),"bible.db");try(SQLiteDatabase stage=SQLiteDatabase.openOrCreateDatabase(file,null)){stage.execSQL("CREATE TABLE IF NOT EXISTS verses(book TEXT NOT NULL,chapter INTEGER NOT NULL,verse INTEGER NOT NULL,value TEXT NOT NULL,PRIMARY KEY(book,chapter,verse))");stage.execSQL("CREATE TABLE IF NOT EXISTS checkpoint(id INTEGER PRIMARY KEY,position INTEGER,value TEXT)");stage.execSQL("CREATE TABLE IF NOT EXISTS titles(book TEXT NOT NULL,chapter INTEGER NOT NULL,verse INTEGER NOT NULL,ord INTEGER NOT NULL,value TEXT NOT NULL,PRIMARY KEY(book,chapter,verse,ord))");try(Cursor checkpoint=stage.rawQuery("SELECT position,value FROM checkpoint WHERE id=1",null)){if(checkpoint.moveToFirst()){int next=checkpoint.getInt(0);if(next<0)data.put("parsed",true).put("verses",DatabaseUtils.longForQuery(stage,"SELECT COUNT(*) FROM verses",null));else data.put("next",next).put("parser",new JSONObject(checkpoint.getString(1)));}else{data.put("next",0).remove("parser");}}final long[] stagedCount={0},lastTextPulse={-1000};String inputKind=MediaFormats.kind(data.getString("name"),data.getString("mime"));final boolean textOnly=!(inputKind.equals("epub")||inputKind.equals("pdf")||inputKind.equals("docx"));BibleText.Sink sink=(book,chapter,verse,text)->{try{stage.insertOrThrow("verses",null,StudyStore.values("book",book,"chapter",chapter,"verse",verse,"value",text));if(textOnly&&++stagedCount[0]%128==0&&SystemClock.elapsedRealtime()-lastTextPulse[0]>=400){lastTextPulse[0]=SystemClock.elapsedRealtime();control.progress("A importar Bíblia · "+stagedCount[0]+" versículos",0,0);}}catch(SQLiteConstraintException e){throw new IOException("Versículo repetido: "+book+" "+chapter+":"+verse);}};
        if(!data.optBoolean("parsed")){String moduleFormat=BibleModuleWork.format(c,data);if(!moduleFormat.isEmpty()){BibleModuleWork.read(c,id,work,data,stage,moduleFormat,sink,control);}else{Uri uri=Uri.parse(data.getString("uri"));String name=data.getString("name"),mime=data.getString("mime"),kind=MediaFormats.kind(name,mime);boolean container=kind.equals("epub")||kind.equals("pdf")||kind.equals("docx");if(!container){stage.beginTransaction();try{stage.delete("verses",null,null);BibleEncoding.parse(()->ApkInstallActivity.openSource(c,uri),sink,()->{stage.delete("verses",null,null);stagedCount[0]=0;},control::cancelled);stage.execSQL("INSERT OR REPLACE INTO checkpoint(id,position,value) VALUES(1,-1,'{}')");stage.setTransactionSuccessful();}finally{stage.endTransaction();}}
        else{if(kind.equals("epub")&&data.optInt("epub_parser")!=2){stage.beginTransaction();try{stage.delete("verses",null,null);stage.delete("checkpoint",null,null);stage.setTransactionSuccessful();}finally{stage.endTransaction();}data.put("next",0).put("epub_parser",2).remove("parser");work.payload(id,data);}int first=data.optInt("next");try(SpeechDocument source=new SpeechDocument(c,uri,name,mime,control::cancelled)){String digest=source.fingerprint();String prior=data.optString("digest");if(!prior.isEmpty()&&!prior.equals(digest))throw new IOException("A Bíblia foi alterada durante a importação. Importe-a novamente.");data.put("digest",digest);work.payload(id,data);JSONObject saved=data.optJSONObject("parser");BibleBookText parser=new BibleBookText(sink,saved==null?new JSONObject():saved);for(int part=first;part<source.count();part++){control.check();final int currentPart=part;final long[] lastPulse={-1000};Runnable pulse=()->{long now=SystemClock.elapsedRealtime();if(now-lastPulse[0]<400)return;lastPulse[0]=now;String label=parser.book.isEmpty()?"A ler a Bíblia":parser.book;control.progress(label+" · "+parser.count+" versículos · "+(currentPart+1)+" / "+source.count(),currentPart,source.count());};pulse.run();stage.beginTransaction();try{if(source.book!=null&&source.book.epub)BibleEpubText.read(source.book,part,parser,control::cancelled,pulse);else{parser.heading(source.partTitle(part,""));parser.feed(source.part(part),()->{pulse.run();return control.cancelled();});}stage.execSQL("CREATE TABLE IF NOT EXISTS checkpoint(id INTEGER PRIMARY KEY,position INTEGER,value TEXT)");stage.execSQL("INSERT OR REPLACE INTO checkpoint(id,position,value) VALUES(1,?,?)",new Object[]{part+1,parser.state().toString()});stage.setTransactionSuccessful();}finally{stage.endTransaction();}data.put("next",part+1).put("parser",parser.state());work.payload(id,data);control.progress("A importar Bíblia · "+(part+1)+" / "+source.count(),part+1,source.count());}stage.beginTransaction();try{parser.flush();stage.execSQL("INSERT OR REPLACE INTO checkpoint(id,position,value) VALUES(1,-1,?)",new Object[]{parser.state().toString()});stage.setTransactionSuccessful();}finally{stage.endTransaction();}}}
        }
        long count=DatabaseUtils.longForQuery(stage,"SELECT COUNT(*) FROM verses",null);if(count==0)throw new IOException("Nenhum versículo reconhecido. Use uma Bíblia com versículos, um módulo MyBible SQLite3 ou ficheiros USX.");data.put("parsed",true).put("verses",count);work.payload(id,data);}
        long actual=DatabaseUtils.longForQuery(stage,"SELECT COUNT(*) FROM verses",null);if(actual<=0||actual!=data.optLong("verses"))throw new IOException("A importação temporária está incompleta. Importe esta Bíblia novamente.");control.check();control.critical=true;try(PlusStore db=new PlusStore(c)){SQLiteDatabase sql=db.getWritableDatabase();long source=data.optLong("source");if(source>0){List<StudyStore.Row> old=db.rows("bible_sources","id=?",new String[]{""+source},null,1);if(!old.isEmpty()&&(!old.get(0).s("title").equals(data.getString("title"))||old.get(0).n("created")!=job.n("created")))source=0;}if(source==0){source=DatabaseUtils.longForQuery(sql,"SELECT coalesce(max(id),0)+1 FROM bible_sources",null);data.put("source",source);work.payload(id,data);}sql.beginTransaction();try{sql.delete("bible_verses","source=?",new String[]{""+source});sql.insertWithOnConflict("bible_sources",null,StudyStore.values("id",source,"title",data.getString("title"),"created",job.n("created")),SQLiteDatabase.CONFLICT_REPLACE);try(Cursor r=stage.rawQuery("SELECT book,chapter,verse,value FROM verses ORDER BY book,chapter,verse",null)){while(r.moveToNext())sql.insertOrThrow("bible_verses",null,StudyStore.values("source",source,"book",r.getString(0),"chapter",r.getInt(1),"verse",r.getInt(2),"value",r.getString(3)));}sql.setTransactionSuccessful();}finally{sql.endTransaction();}BibleTitles.publish(c,source,stage);}finally{control.critical=false;}
        control.progress(data.getLong("verses")+" "+AppLanguage.text(c,"versículos importados"),data.getLong("verses"),data.getLong("verses"));
    }}
    private BibleWork(){}
}
